import{_ as t,o,c as n,a0 as a}from"./chunks/framework.DVUHX04-.js";const l=JSON.parse('{"title":"Quota extension refreshes the ChatGPT token itself","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0005-quota-owns-chatgpt-token-refresh.md","filePath":"adr/0005-quota-owns-chatgpt-token-refresh.md","lastUpdated":1789316004000}'),s={name:"adr/0005-quota-owns-chatgpt-token-refresh.md"};function r(i,e,h,d,c,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="quota-extension-refreshes-the-chatgpt-token-itself" tabindex="-1">Quota extension refreshes the ChatGPT token itself <a class="header-anchor" href="#quota-extension-refreshes-the-chatgpt-token-itself" aria-label="Permalink to &quot;Quota extension refreshes the ChatGPT token itself&quot;">​</a></h1><p>The Quota extension reads the <code>openai-codex</code> OAuth entry from pi&#39;s <code>~/.pi/agent/auth.json</code> and, when the access token is expired, refreshes it through the same endpoint and client id pi&#39;s bundled OAuth uses (<code>POST https://auth.openai.com/oauth/token</code>, <code>grant_type=refresh_token</code>), then writes the new token pair back to <code>auth.json</code>.</p><p>pi itself only refreshes the token when the openai-codex model is actually in use, so a session running another provider would sit on an expired token. Reading Codex CLI&#39;s <code>~/.codex/auth.json</code> was rejected: it couples the extension to a tool that may not be installed or run, and a token refreshed there would not flow back to pi. Duplicating pi&#39;s refresh is the price of the extension working from any session.</p><p>Because both pi and the extension can refresh the same login, and ChatGPT refresh tokens rotate, the extension refreshes only on expiry or 401, does a read-modify-write on <code>auth.json</code>, and retries once after re-reading before declaring the login dead and asking the user to log in again.</p>',4)])])}const u=t(s,[["render",r]]);export{l as __pageData,u as default};
